[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/types.ts", "content": "/**
 * Types for Qwen Code CLI transcript parsing.
 *
 * Qwen Code records each conversation as a JSONL file where every line is a
 * `ChatRecord`. Records form a tree via `uuid` / `parentUuid` and carry the
 * message content in Gemini's `parts` format (text, functionCall,
 * functionResponse), since Qwen Code is built on the Gemini CLI codebase.
 */

/**
 * A text part in a Gemini-format message. `thought` marks internal reasoning
 * that should be excluded from user-facing text by default.
 */
export interface GeminiTextPart {
  text: string;
  thought?: boolean;
}

/**
 * A function (tool) call emitted by the model.
 */
export interface GeminiFunctionCallPart {
  functionCall: {
    id: string;
    name: string;
    args?: Record<string, any>;
  };
}

/**
 * The result of a tool call, fed back to the model.
 */
export interface GeminiFunctionResponsePart {
  functionResponse: {
    id: string;
    name: string;
    response: any;
  };
}

/**
 * Union of the message part shapes that appear in a ChatRecord message.
 */
export type GeminiPart = GeminiTextPart | GeminiFunctionCallPart | GeminiFunctionResponsePart;

/**
 * Structured message payload: a role plus an ordered array of parts.
 */
export interface GeminiMessage {
  role: string;
  parts: GeminiPart[];
}

/**
 * The result attached to a `tool_result` record.
 */
export interface ToolCallResult {
  callId: string;
  status: string;
  resultDisplay?: any;
}

/**
 * Token accounting for a single model call, in Gemini's naming.
 */
export interface UsageMetadata {
  promptTokenCount: number;
  candidatesTokenCount: number;
  totalTokenCount: number;
}

/**
 * A single line in a Qwen Code JSONL transcript.
 */
export interface ChatRecord {
  uuid: string;
  parentUuid: string | null;
  sessionId: string;
  timestamp: string;
  type: 'user' | 'assistant' | 'system' | 'tool_result';
  message?: GeminiMessage | string;
  toolCallResult?: ToolCallResult;
  usageMetadata?: UsageMetadata;
  model?: string;
}

/**
 * OpenAI chat-format tool call, used on assistant messages.
 */
export interface ToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * OpenAI chat-format message used in LLM span inputs. Matches the message
 * structure the MLflow UI Chat view renders.
 */
export interface OpenAIMessage {
  role: 'user' | 'assistant' | 'system' | 'tool';
  content: string | null;
  tool_calls?: ToolCall[];
  tool_call_id?: string;
}
