[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/transcript.ts", "content": "/**
 * Transcript parsing utilities for Qwen Code CLI JSONL files.
 *
 * Each line of a transcript is a `ChatRecord`. Messages use Gemini's `parts`
 * format, so the helpers here know how to pull text, function calls, and
 * function responses out of a record regardless of whether the message is a
 * structured object or a plain string.
 */

import { readFileSync } from 'node:fs';
import type {
  ChatRecord,
  GeminiPart,
  GeminiFunctionCallPart,
  GeminiFunctionResponsePart,
  GeminiTextPart,
} from './types.js';

export const NANOSECONDS_PER_MS = 1e6;

/**
 * Read and parse a Qwen Code JSONL transcript file into ChatRecords.
 */
export function readTranscript(path: string): ChatRecord[] {
  const content = readFileSync(path, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as ChatRecord);
}

/**
 * Parse an ISO 8601 timestamp string to nanoseconds since the Unix epoch
 * (epoch milliseconds * 1,000,000). Returns null for null/undefined/empty
 * input or unparseable timestamps.
 */
export function parseTimestampToNs(timestamp: string | null | undefined): number | null {
  if (!timestamp) {
    return null;
  }
  const ms = new Date(timestamp).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return ms * NANOSECONDS_PER_MS;
}

/**
 * Type guard: true when a GeminiPart carries text content.
 */
export function isTextPart(part: GeminiPart): part is GeminiTextPart {
  return part != null && typeof (part as GeminiTextPart).text === 'string';
}

/**
 * Type guard: true when a GeminiPart carries a function call.
 */
export function isFunctionCallPart(part: GeminiPart): part is GeminiFunctionCallPart {
  return part != null && (part as GeminiFunctionCallPart).functionCall != null;
}

/**
 * Type guard: true when a GeminiPart carries a function response.
 */
export function isFunctionResponsePart(part: GeminiPart): part is GeminiFunctionResponsePart {
  return part != null && (part as GeminiFunctionResponsePart).functionResponse != null;
}

/**
 * Extract text content from a ChatRecord's message.
 *
 * Joins all non-thought text parts with a newline. Thought parts (internal
 * reasoning) are excluded unless `includeThoughts` is true. A plain string
 * message is returned as-is. functionCall / functionResponse parts contribute
 * no text and are silently skipped.
 */
export function getMessageText(record: ChatRecord, includeThoughts = false): string {
  const message = record.message;
  if (message == null) {
    return '';
  }
  if (typeof message === 'string') {
    return message;
  }
  const parts = message.parts ?? [];
  return parts
    .filter(isTextPart)
    .filter((part) => includeThoughts || !part.thought)
    .map((part) => part.text)
    .join('\n');
}

/**
 * Extract all functionCall parts from a ChatRecord's message. Returns an empty
 * array when the record has no message or no functionCall parts.
 */
export function getFunctionCalls(
  record: ChatRecord,
): Array<{ id: string; name: string; args?: Record<string, any> }> {
  const message = record.message;
  if (message == null || typeof message === 'string') {
    return [];
  }
  const parts = message.parts ?? [];
  return parts.filter(isFunctionCallPart).map((part) => ({
    id: part.functionCall.id,
    name: part.functionCall.name,
    args: part.functionCall.args,
  }));
}

/**
 * Build a map from `toolCallResult.callId` to the `tool_result` record that
 * carries it. Non-tool_result records are excluded.
 */
export function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {
  const map = new Map<string, ChatRecord>();
  for (const record of records) {
    if (record.type !== 'tool_result') {
      continue;
    }
    const callId = record.toolCallResult?.callId;
    if (callId) {
      map.set(callId, record);
    }
  }
  return map;
}

/**
 * Normalize a resultDisplay value to a string. String values pass through
 * unchanged, objects are JSON.stringified, and null/undefined become the empty
 * string.
 */
export function formatResultDisplay(display: any): string {
  if (display == null) {
    return '';
  }
  if (typeof display === 'string') {
    return display;
  }
  return JSON.stringify(display);
}

/**
 * Extract tool output from a `tool_result` record.
 *
 * Prefers `toolCallResult.resultDisplay` (passed through formatResultDisplay).
 * When resultDisplay is absent, falls back to JSON.stringify of the
 * functionResponse.response found in the message parts. Returns the empty
 * string when neither is available.
 */
export function getToolOutput(record: ChatRecord): string {
  const resultDisplay = record.toolCallResult?.resultDisplay;
  if (resultDisplay != null) {
    return formatResultDisplay(resultDisplay);
  }

  const message = record.message;
  if (message != null && typeof message !== 'string') {
    const parts = message.parts ?? [];
    for (const part of parts) {
      if (isFunctionResponsePart(part)) {
        return JSON.stringify(part.functionResponse.response);
      }
    }
  }
  return '';
}

/**
 * Extract token counts from a usageMetadata object. Maps promptTokenCount to
 * `input`, candidatesTokenCount to `output`, and totalTokenCount to `total`.
 * Returns null when the argument is undefined or missing.
 */
export function getTokenUsage(
  usageMetadata: any,
): { input: number; output: number; total: number } | null {
  if (usageMetadata == null) {
    return null;
  }
  return {
    input: usageMetadata.promptTokenCount,
    output: usageMetadata.candidatesTokenCount,
    total: usageMetadata.totalTokenCount,
  };
}

/**
 * Return the records belonging to the last turn: a slice starting at the last
 * record with type === 'user' through the end of the array.
 */
export function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {
  let lastUserIndex = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    if (records[i].type === 'user') {
      lastUserIndex = i;
      break;
    }
  }
  if (lastUserIndex === -1) {
    return records;
  }
  return records.slice(lastUserIndex);
}
