 * MLflow tracing integration for Qwen Code CLI.
 *
 * Reads a Qwen Code JSONL transcript and reconstructs it as an MLflow trace:
 * an AGENT root span for the whole conversation, one LLM span per assistant
 * turn, and one TOOL span per function call. Span inputs/outputs are rendered
 * in OpenAI chat-completion format so the MLflow Chat view can display them.
 */

import {
  startSpan,
  flushTraces,
  InMemoryTraceManager,
  SpanStatusCode,
  SpanType,
  SpanAttributeKey,
  TraceMetadataKey,
  TokenUsageKey,
} from '@mlflow/core';

import type { ChatRecord, OpenAIMessage } from './types.js';
import {
  parseTimestampToNs,
  getMessageText,
  getFunctionCalls,
  buildToolResultMap,
  getToolOutput,
  getTokenUsage,
  readTranscript,
} from './transcript.js';

/**
 * Reconstruct OpenAI chat-format message history from the records preceding
 * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view
 * shows the full conversation context that led up to each assistant call.
 *
 * - user            → `{ role: 'user', content }`
 * - assistant text  → `{ role: 'assistant', content }` (thought parts excluded)
 * - assistant tools → `{ role: 'assistant', content: null, tool_calls: [...] }`
 * - tool_result     → `{ role: 'tool', tool_call_id, content }`
 * - system w/ msg   → `{ role: 'system', content }`
 * - system w/o msg  → skipped
 */
export function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {
  const messages: OpenAIMessage[] = [];

  for (let i = 0; i < targetIndex; i++) {
    const record = records[i];

    if (record.type === 'user') {
      messages.push({ role: 'user', content: getMessageText(record) });
    } else if (record.type === 'assistant') {
      const functionCalls = getFunctionCalls(record);
      if (functionCalls.length > 0) {
        messages.push({
          role: 'assistant',
          content: null,
          tool_calls: functionCalls.map((fc) => ({
            id: fc.id,
            type: 'function',
            function: {
              name: fc.name,
              arguments: JSON.stringify(fc.args ?? {}),
            },
          })),
        });
      } else {
        messages.push({ role: 'assistant', content: getMessageText(record) });
      }
    } else if (record.type === 'tool_result') {
      messages.push({
        role: 'tool',
        tool_call_id: record.toolCallResult?.callId ?? '',
        content: getToolOutput(record),
      });
    } else if (record.type === 'system') {
      // System records without a message carry no content and are excluded.
      if (record.message != null) {
        messages.push({ role: 'system', content: getMessageText(record) });
      }
    }
  }

  return messages;
}

/**
 * Read a Qwen Code JSONL transcript and convert it into an MLflow trace.
