import {
  parseTimestampToNs,
  getMessageText,
  getFunctionCalls,
  isTextPart,
  isFunctionCallPart,
  formatResultDisplay,
  getToolOutput,
  getTokenUsage,
  getLastTurnRecords,
} from '../src/transcript';
import type { ChatRecord } from '../src/types';

it('parseTimestampToNs', () => {
  expect(parseTimestampToNs('2026-04-05T10:00:00Z')).toBe(new Date('2026-04-05T10:00:00Z').getTime() * 1e6);
  expect(parseTimestampToNs(null)).toBeNull();
  expect(parseTimestampToNs(undefined)).toBeNull();
  expect(parseTimestampToNs('')).toBeNull();
});

it('getMessageText thoughts + string + skip', () => {
  const rec: ChatRecord = {
    uuid: 'a', parentUuid: null, sessionId: 's', timestamp: 't', type: 'assistant',
    message: { role: 'model', parts: [
      { text: 'think', thought: true },
      { text: 'line1' },
      { functionCall: { id: 'c', name: 'n', args: {} } },
      { text: 'line2' },
    ] },
  };
  expect(getMessageText(rec)).toBe('line1\nline2');
  expect(getMessageText(rec, true)).toBe('think\nline1\nline2');
  const str: ChatRecord = { ...rec, message: 'plain' };
  expect(getMessageText(str)).toBe('plain');
  const none: ChatRecord = { ...rec, message: undefined };
  expect(getMessageText(none)).toBe('');
});

it('getFunctionCalls', () => {
  const rec: ChatRecord = {
    uuid: 'a', parentUuid: null, sessionId: 's', timestamp: 't', type: 'assistant',
    message: { role: 'model', parts: [{ text: 'x' }, { functionCall: { id: 'c1', name: 'f', args: { a: 1 } } }] },
  };
  expect(getFunctionCalls(rec)).toEqual([{ id: 'c1', name: 'f', args: { a: 1 } }]);
  expect(getFunctionCalls({ ...rec, message: undefined })).toEqual([]);
  expect(getFunctionCalls({ ...rec, message: { role: 'm', parts: [{ text: 'x' }] } })).toEqual([]);
});

it('type guards', () => {
  expect(isTextPart({ text: 'x' })).toBe(true);
  expect(isTextPart({ functionCall: { id: 'a', name: 'b' } } as any)).toBe(false);
  expect(isFunctionCallPart({ functionCall: { id: 'a', name: 'b' } })).toBe(true);
  expect(isFunctionCallPart({ text: 'x' } as any)).toBe(false);
});

it('formatResultDisplay', () => {
  expect(formatResultDisplay('str')).toBe('str');
  expect(formatResultDisplay({ a: 1 })).toBe('{"a":1}');
  expect(formatResultDisplay(null)).toBe('');
  expect(formatResultDisplay(undefined)).toBe('');
});

it('getToolOutput fallback', () => {
  const withDisplay: ChatRecord = {
    uuid: 'a', parentUuid: null, sessionId: 's', timestamp: 't', type: 'tool_result',
    toolCallResult: { callId: 'c', status: 'ok', resultDisplay: { x: 1 } },
