  const fallback: ChatRecord = {
    uuid: 'a', parentUuid: null, sessionId: 's', timestamp: 't', type: 'tool_result',
    toolCallResult: { callId: 'c', status: 'ok' },
    message: { role: 'user', parts: [{ functionResponse: { id: 'c', name: 'n', response: { r: 2 } } }] },
  };
  expect(getToolOutput(fallback)).toBe('{"r":2}');
  const neither: ChatRecord = {
    uuid: 'a', parentUuid: null, sessionId: 's', timestamp: 't', type: 'tool_result',
    toolCallResult: { callId: 'c', status: 'ok' },
  };
  expect(getToolOutput(neither)).toBe('');
});

it('getTokenUsage', () => {
  expect(getTokenUsage({ promptTokenCount: 1, candidatesTokenCount: 2, totalTokenCount: 3 })).toEqual({ input: 1, output: 2, total: 3 });
