},\n      attributes: { ...(options.attributes ?? {}) },\n      startTimeNs: options.startTimeNs ?? null,\n      endTimeNs: null,\n      statusCode: null as string | null,\n      statusMessage: null as string | null,\n      setAttribute: jest.fn((key: string, value: any) => {\n        span.attributes[key] = value;\n      }),\n      setStatus: jest.fn((code: string, message?: string) => {\n        span.statusCode = code;\n        span.statusMessage = message ?? null;\n      }),\n      end: jest.fn((opts?: any) => {\n        if (opts?.outputs) span.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'STATUS_CODE_OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'STATUS_CODE_UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: {\n    getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })),\n  },\n}));\n\nimport { resolve } from 'path';\nimport { processTranscript } from '../src/tracing';\nimport { flushTraces } from '@mlflow/core';\n\nconst FIX = resolve(__dirname, 'fixtures', 'with-tool-call.jsonl');\nconst spans = () => Object.values(mockSpans);\nconst byType = (t: string) => spans().filter((s) => s.spanType === t);\nconst root = () => spans().find((s) => s.parentId == null);\nconst parseNs = (iso: string) => new Date(iso).getTime() * 1_000_000;\n\nbeforeEach(() => {\n  spanCounter = 0;\n  Object.keys(mockSpans).forEach((k) => delete mockSpans[k]);\n  mockTraceInfo.traceMetadata = {};\n  jest.clearAllMocks();\n});\n\nit('null path: no spans, no flush', async () => {\n  await processTranscript(null, 'sess-1');\n  expect(spans().length).toBe(0);\n  expect(flushTraces).not.toHaveBeenCalled();\n});\n\nit('builds AGENT/LLM/TOOL tree with correct data', async () => {\n  await processTranscript(FIX, 'sess-1');\n\n  const r = root();\n  expect(r.name).toBe('qwen_code_conversation');\n  expect(r.spanType).toBe('AGENT');\n  expect(r.inputs).toBe('list files in current directory');\n  expect(r.startTimeNs).toBe(parseNs('2026-04-05T10:00:00Z'));\n\n  const rootEnd = (r.end as jest.Mock).mock.calls[0][0];\n  expect(rootEnd.outputs).toBe('There are 2 files.');\n  expect(rootEnd.endTimeNs).toBe(parseNs('2026-04-05T10:00:04Z'));\n\n  // root token usage: input=last prompt(150), output=sum candidates(10+20=30)\n  expect(r.attributes['mlflow.chat.tokenUsage']).toEqual({\n    input_tokens: 150,\n    output_tokens: 30,\n    total_tokens: 180,\n  });\n\n  const llm = byType('LLM');\n  expect(llm.length).toBe(2);\n  const tool = byType('TOOL');\n  expect(tool.length).toBe(1);\n\n  // LLM 1 outputs exclude thought part\n  const llm1End = (llm[0].end as jest.Mock).mock.calls[0][0];\n  expect(llm1End.outputs).toEqual({\n    choices: [{ message: { role: 'assistant', content: \"I'll list the files.\" } }],\n  });\n  // LLM1 timing: preceding record (user@00) -> own (a1@01)\n  expect(llm[0].startTimeNs).toBe(parseNs('2026-04-05T10:00:00Z'));\n  expect(llm[0].endTimeNs).toBe(parseNs('2026-04-05T10:00:01Z'));\n  // LLM1 inputs\n  expect(llm[0].inputs).toEqual({\n    model: 'qwen-max',\n    messages: [{ role: 'user', content: 'list files in current directory' }],\n  });\n  // per-call token usage\n  expect(llm[0].attributes['mlflow.chat.tokenUsage']).toEqual({\n    input_tokens: 100,\n    output_tokens: 10,\n    total_tokens: 110,\n  });\n\n  // LLM 2 inputs include reconstructed history with tool_calls + tool msg\n  expect(llm[1].inputs).toEqual({\n    model: 'qwen-max',\n    messages: [\n      { role: 'user', content: 'list files in current directory' },\n      {\n        role: 'assistant',\n        content: null,\n        tool_calls: [\n          { id: 'call_1', type: 'function', function: { name: 'list_dir', arguments: '{\"path\":\".\"}' } },\n        ],\n      },\n      { role: 'tool', tool_call_id: 'call_1', content: 'file1.txt\\nfile2.txt' },\n    ],\n  });\n  // LLM2 timing: preceding record (tool_result@03) -> own (a2@04)\n  expect(llm[1].startTimeNs).toBe(parseNs('2026-04-05T10:00:03Z'));\n  expect(llm[1].endTimeNs).toBe(parseNs('2026-04-05T10:00:04Z'));\n\n  // TOOL span\n  expect(tool[0].name).toBe('tool_list_dir');\n  expect(tool[0].attributes.tool_id).toBe('call_1');\n  expect(tool[0].inputs).toEqual({ path: '.' });\n  expect(tool[0].startTimeNs).toBe(parseNs('2026-04-05T10:00:01Z'));\n  expect(tool[0].endTimeNs).toBe(parseNs('2026-04-05T10:00:03Z'));\n  const toolEnd = (tool[0].end as jest.Mock).mock.calls[0][0];\n  expect(toolEnd.outputs).toEqual({ result: 'file1.txt\\nfile2.txt' });\n  expect(tool[0].setStatus).not.toHaveBeenCalled();\n\n  // session metadata\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.user']).toBeDefined();\n\n  expect(flushTraces).toHaveBeenCalled();\n});\n\nit('cancelled tool sets ERROR status with message containing cancelled', async () => {\n  const CFIX = resolve(__dirname, 'fixtures', 'cancelled.jsonl');\n  await processTranscript(CFIX, 'sess-2');\n  const tool = byType('TOOL');\n  expect(tool.length).toBe(1);\n  expect(tool[0].setStatus).toHaveBeenCalled();\n  expect(tool[0].statusCode).toBe('STATUS_CODE_ERROR');\n  expect(tool[0].statusMessage.toLowerCase()).toContain('cancelled');\n});\n"],"version":3}
