AAC;QACJ,CAAC;IACH,CAAC;IAED,QAAQ,CAAC,GAAG,CAAC;QACX,OAAO,EAAE,aAAa,CAAC,CAAC,CAAC,IAAA,8BAAc,EAAC,aAAa,CAAC,CAAC,CAAC,CAAC,EAAE;QAC3D,GAAG,CAAC,SAAS,IAAI,IAAI,CAAC,CAAC,CAAC,EAAE,SAAS,EAAE,SAAS,EAAE,CAAC,CAAC,CAAC,EAAE,CAAC;KACvD,CAAC,CAAC;IAEH,MAAM,IAAA,kBAAW,GAAE,CAAC;AACtB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/qwen-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Qwen Code CLI.\n *\n * Reads a Qwen Code JSONL transcript and reconstructs it as an MLflow trace:\n * an AGENT root span for the whole conversation, one LLM span per assistant\n * turn, and one TOOL span per function call. Span inputs/outputs are rendered\n * in OpenAI chat-completion format so the MLflow Chat view can display them.\n */\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TraceMetadataKey,\n  TokenUsageKey,\n} from '@mlflow/core';\n\nimport type { ChatRecord, OpenAIMessage } from './types.js';\nimport {\n  parseTimestampToNs,\n  getMessageText,\n  getFunctionCalls,\n  buildToolResultMap,\n  getToolOutput,\n  getTokenUsage,\n  readTranscript,\n} from './transcript.js';\n\n/**\n * Reconstruct OpenAI chat-format message history from the records preceding\n * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view\n * shows the full conversation context that led up to each assistant call.\n *\n * - user            → `{ role: 'user', content }`\n * - assistant text  → `{ role: 'assistant', content }` (thought parts excluded)\n * - assistant tools → `{ role: 'assistant', content: null, tool_calls: [...] }`\n * - tool_result     → `{ role: 'tool', tool_call_id, content }`\n * - system w/ msg   → `{ role: 'system', content }`\n * - system w/o msg  → skipped\n */\nexport function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {\n  const messages: OpenAIMessage[] = [];\n\n  for (let i = 0; i < targetIndex; i++) {\n    const record = records[i];\n\n    if (record.type === 'user') {\n      messages.push({ role: 'user', content: getMessageText(record) });\n    } else if (record.type === 'assistant') {\n      const functionCalls = getFunctionCalls(record);\n      if (functionCalls.length > 0) {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: functionCalls.map((fc) => ({\n            id: fc.id,\n            type: 'function',\n            function: {\n              name: fc.name,\n              arguments: JSON.stringify(fc.args ?? {}),\n            },\n          })),\n        });\n      } else {\n        messages.push({ role: 'assistant', content: getMessageText(record) });\n      }\n    } else if (record.type === 'tool_result') {\n      messages.push({\n        role: 'tool',\n        tool_call_id: record.toolCallResult?.callId ?? '',\n        content: getToolOutput(record),\n      });\n    } else if (record.type === 'system') {\n      // System records without a message carry no content and are excluded.\n      if (record.message != null) {\n        messages.push({ role: 'system', content: getMessageText(record) });\n      }\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Read a Qwen Code JSONL transcript and convert it into an MLflow trace.\n *\n * When `transcriptPath` is null, returns immediately without creating any\n * spans or flushing. Otherwise builds the AGENT/LLM/TOOL span tree, attaches\n * timing, token usage, and session metadata, and flushes the trace.\n */\nexport async function processTranscript(\n  transcriptPath: string | null,\n  sessionId?: string,\n): Promise<void> {\n  if (transcriptPath == null) {\n    return;\n  }\n\n  const records = readTranscript(transcriptPath);\n\n  const firstUser = records.find((r) => r.type === 'user');\n  const assistantRecords = records.filter((r) => r.type === 'assistant');\n  const lastAssistant = assistantRecords[assistantRecords.length - 1];\n  const toolResults = buildToolResultMap(records);\n\n  const rootStartNs = parseTimestampToNs(firstUser?.timestamp);\n  const rootEndNs = parseTimestampToNs(lastAssistant?.timestamp);\n\n  // Root AGENT span. The user prompt is passed as a raw string so MLflow can\n  // auto-generate the request preview and render the session view cleanly.\n  const rootSpan = startSpan({\n    name: 'qwen_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: firstUser ? getMessageText(firstUser) : '',\n    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),\n  });\n\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i];\n    if (record.type !== 'assistant') {\n      continue;\n    }\n\n    const timestampNs = parseTimestampToNs(record.timestamp);\n    const prevNs = parseTimestampToNs(records[i - 1]?.timestamp);\n    const model = record.model ?? 'unknown';\n\n    // LLM span: from the preceding record to this assistant record.\n    const llmSpan = startSpan({\n      name: 'llm_call',\n      parent: rootSpan,\n      spanType: SpanType.LLM,\n      inputs: {\n        model,\n        messages: reconstructMessages(records, i),\n      },\n      attributes: { model },\n      ...(prevNs != null ? { startTimeNs: prevNs } : timestampNs != null ? { startTimeNs: timestampNs } : {}),\n    });\n\n    const usage = getTokenUsage(record.usageMetadata);\n    if (usage) {\n      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n        [TokenUsageKey.INPUT_TOKENS]: usage.input,\n        [TokenUsageKey.OUTPUT_TOKENS]: usage.output,\n        [TokenUsageKey.TOTAL_TOKENS]: usage.total,\n      });\n    }\n\n    llmSpan.end({\n      outputs: {\n        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],\n      },\n      ...(timestampNs != null ? { endTimeNs: timestampNs } : {}),\n    });\n\n    // TOOL span per function call within this assistant record.\n    for (const fc of getFunctionCalls(record)) {\n      const resultRecord = toolResults.get(fc.id);\n      const toolEndNs = parseTimestampToNs(resultRecord?.timestamp);\n\n      const toolSpan = startSpan({\n        name: `tool_${fc.name}`,\n        parent: rootSpan,\n        spanType: SpanType.TOOL,\n        inputs: fc.args ?? {},\n        attributes: { tool_name: fc.name, tool_id: fc.id },\n        ...(timestampNs != null ? { startTimeNs: timestampNs } : {}),\n      });\n\n      // A cancelled tool call is surfaced as an error span; successful calls\n      // keep the default (unset) status.\n      if (resultRecord?.toolCallResult?.status === 'cancelled') {\n        toolSpan.setStatus(SpanStatusCode.ERROR, 'Tool call cancelled');\n      }\n\n      toolSpan.end({\n        outputs: { result: resultRecord ? getToolOutput(resultRecord) : '' },\n        ...(toolEndNs != null ? { endTimeNs: toolEndNs } : timestampNs != null ? { endTimeNs: timestampNs } : {}),\n      });\n    }\n  }\n\n  // Root-level token usage: input reflects the final prompt size (last\n  // assistant call), output is the sum of tokens generated across all calls.\n  if (assistantRecords.length > 0) {\n    const inputTokens = lastAssistant.usageMetadata?.promptTokenCount ?? 0;\n    const outputTokens = assistantRecords.reduce(\n      (sum, r) => sum + (r.usageMetadata?.candidatesTokenCount ?? 0),\n      0,\n    );\n    rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n      [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n      [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n      [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n    });\n  }\n\n  // Attach session/user metadata to the trace. We use InMemoryTraceManager\n  // directly because `updateCurrentTrace()` requires an active OTel span\n  // context, which transcript-based processing doesn't have — spans are\n  // created via `startSpan()` without OTel context propagation.\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: sessionId ?? '',\n        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? 'unknown',\n      };\n    }\n  }\n\n  rootSpan.end({\n    outputs: lastAssistant ? getMessageText(lastAssistant) : '',\n    ...(rootEndNs != null ? { endTimeNs: rootEndNs } : {}),\n  });\n\n  await flushTraces();\n}\n"],"version":3}
